import AppKit
import ApplicationServices

/// Polls the general pasteboard; macOS has no change notification for it.
final class ClipboardMonitor {
    static let shared = ClipboardMonitor()

    private var lastChange = NSPasteboard.general.changeCount
    private var timer: Timer?

    /// Markers from nspasteboard.org that password managers and similar apps set.
    private static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.4, repeats: true) { [weak self] _ in self?.poll() }
        RunLoop.main.add(timer!, forMode: .common)
    }

    /// Call after ClipNest itself writes to the pasteboard so the write is not recorded again.
    func ignoreCurrentChange() {
        lastChange = NSPasteboard.general.changeCount
    }

    private func poll() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChange else { return }
        lastChange = pb.changeCount

        let s = AppSettings.shared
        if s.paused { return }
        let front = NSWorkspace.shared.frontmostApplication
        if let bid = front?.bundleIdentifier, s.excludedBundleIDs.contains(bid) { return }
        let types = Set((pb.types ?? []).map(\.rawValue))
        if s.ignoreConcealed, !types.isDisjoint(with: Self.privateTypes) { return }

        if let item = capture(pb, types: types, app: front) {
            ClipStore.shared.add(item)
        }
    }

    private func capture(_ pb: NSPasteboard, types: Set<String>, app: NSRunningApplication?) -> ClipItem? {
        let appName = app?.localizedName
        let bundleID = app?.bundleIdentifier

        // Files first: Finder also puts icons and names on the pasteboard.
        if let urls = pb.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            return ClipItem(kind: .file, text: urls.map(\.path).joined(separator: "\n"),
                            filePaths: urls.map(\.path), sourceAppName: appName, sourceBundleID: bundleID)
        }

        // Text next: office apps attach a picture of copied text, which should stay text.
        if let str = pb.string(forType: .string), !str.isEmpty {
            return ClipItem(kind: .text, text: str, rtf: pb.data(forType: .rtf),
                            sourceAppName: appName, sourceBundleID: bundleID)
        }

        if let png = pngData(from: pb) {
            let (name, hash) = ClipStore.shared.storeImage(png)
            let size = NSBitmapImageRep(data: png).map { CGSize(width: $0.pixelsWide, height: $0.pixelsHigh) }
            return ClipItem(kind: .image, imageName: name, imageHash: hash, imageSize: size,
                            sourceAppName: appName, sourceBundleID: bundleID)
        }
        return nil
    }

    private func pngData(from pb: NSPasteboard) -> Data? {
        if let png = pb.data(forType: .png) { return png }
        guard let tiff = pb.data(forType: .tiff) ?? NSImage(pasteboard: pb)?.tiffRepresentation,
              let rep = NSBitmapImageRep(data: tiff) else { return nil }
        return rep.representation(using: .png, properties: [:])
    }
}

enum Paster {
    /// Puts a clip back on the pasteboard. A transform always produces plain text.
    static func write(_ item: ClipItem, plain: Bool = false, transform: TextTransform? = nil) {
        let pb = NSPasteboard.general
        pb.clearContents()
        switch item.kind {
        case .text:
            let raw = item.text ?? ""
            if let t = transform {
                pb.setString(t.apply(raw), forType: .string)
            } else {
                if !plain, let rtf = item.rtf { pb.setData(rtf, forType: .rtf) }
                pb.setString(raw, forType: .string)
            }
        case .image:
            if let url = ClipStore.shared.imageURL(item), let data = try? Data(contentsOf: url) {
                pb.setData(data, forType: .png)
                if let tiff = NSImage(data: data)?.tiffRepresentation { pb.setData(tiff, forType: .tiff) }
            }
        case .file:
            let urls = (item.filePaths ?? []).map { URL(fileURLWithPath: $0) as NSURL }
            pb.writeObjects(urls)
        }
        ClipboardMonitor.shared.ignoreCurrentChange()
        ClipStore.shared.bump(item.id)
    }

    static func write(text: String) {
        let pb = NSPasteboard.general
        pb.clearContents()
        pb.setString(text, forType: .string)
        ClipboardMonitor.shared.ignoreCurrentChange()
    }

    static var hasAccessibility: Bool { AXIsProcessTrusted() }

    static func requestAccessibility() {
        let key = kAXTrustedCheckOptionPrompt.takeUnretainedValue() as String
        _ = AXIsProcessTrustedWithOptions([key: true] as CFDictionary)
    }

    /// Terminals only paste text on ⌘V. TUI apps such as Claude Code read
    /// clipboard images when they receive Ctrl+V instead.
    private static let terminalBundleIDs: Set<String> = [
        "com.mitchellh.ghostty",
        "com.apple.Terminal",
        "com.googlecode.iterm2",
        "dev.warp.Warp-Stable",
        "net.kovidgoyal.kitty",
        "org.alacritty",
        "com.github.wez.wezterm",
    ]

    /// Sends the paste shortcut to the target app. Needs Accessibility permission.
    static func pasteIntoFrontApp(kind: ClipKind = .text, target: NSRunningApplication? = nil) {
        guard AppSettings.shared.autoPaste else { return }
        guard hasAccessibility else { requestAccessibility(); return }
        let bundleID = (target ?? NSWorkspace.shared.frontmostApplication)?.bundleIdentifier ?? ""
        let modifier: CGEventFlags = kind == .image && terminalBundleIDs.contains(bundleID) ? .maskControl : .maskCommand
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.12) {
            let src = CGEventSource(stateID: .combinedSessionState)
            let vKey: CGKeyCode = 9
            let down = CGEvent(keyboardEventSource: src, virtualKey: vKey, keyDown: true)
            let up = CGEvent(keyboardEventSource: src, virtualKey: vKey, keyDown: false)
            down?.flags = modifier
            up?.flags = modifier
            down?.post(tap: .cghidEventTap)
            up?.post(tap: .cghidEventTap)
        }
    }
}
